<template>
  <div class="home-view">
    <NavBarVue />

    <b-row class="mt-2 m-1">
      <b-col>
        <p class="text-light">
          <b>Visão Geral: </b>
          <small style="font-size: 10pt" v-date-format="today"></small>
        </p>
      </b-col>
    </b-row>
    <b-overlay :show="isLoading" rounded="sm">
      <b-row class="m-1">
        <b-col lg="3" md="4" sm="12" class="mb-2">
          <b-card bg-variant="info" text-variant="white">
            <b-row>
              <b-col cols="3" style="font-size: 2.5rem" class="text-center"
                ><b-icon
                  icon="people-fill"
                  class="rounded-circle bg-secondary p-2"
                  variant="light"
                ></b-icon
              ></b-col>
              <b-col>
                Mutuários<br /><b>{{ customers.length }}</b>
                <b-row
                  ><b-col class="text-right"
                    ><b-badge
                      variant="secondary"
                      pill
                      style="cursor: pointer; font-size: 12pt"
                      @click="goToCustomers()"
                      ><b-icon icon="eye" aria-hidden="true"></b-icon>
                      <small> Visualizar</small></b-badge
                    ></b-col
                  ></b-row
                >
              </b-col>
            </b-row>
          </b-card>
        </b-col>
        <b-col lg="3" md="4" sm="12" class="mb-2">
          <b-card bg-variant="success" text-variant="white">
            <b-row>
              <b-col cols="3" style="font-size: 2.5rem" class="text-center"
                ><b-icon
                  icon="credit-card-fill"
                  class="rounded-circle bg-primary p-2"
                  variant="light"
                ></b-icon
              ></b-col>
              <b-col>
                Crédito desenbolsado<br /><b v-money-format="activeLoans" />
              </b-col>
            </b-row>
          </b-card>
        </b-col>
        <b-col lg="3" md="4" sm="12" class="mb-2">
          <b-card bg-variant="info" text-variant="white">
            <b-row>
              <b-col cols="3" style="font-size: 2.5rem" class="text-center"
                ><b-icon
                  icon="calendar-plus-fill"
                  class="rounded-circle bg-primary p-2"
                  variant="light"
                ></b-icon
              ></b-col>
              <b-col>
                Crédito pendente<br /><b v-money-format="pendingLoans" />
                <b-row
                  ><b-col class="text-right"
                    ><b-badge
                      variant="secondary"
                      @click="selectLoanList(1)"
                      pill
                      style="cursor: pointer; font-size: 12pt"
                      ><b-icon icon="eye" aria-hidden="true"></b-icon>
                      <small> Visualizar</small></b-badge
                    ></b-col
                  ></b-row
                >
              </b-col>
            </b-row>
          </b-card>
        </b-col>
        <b-col lg="3" md="4" sm="12" class="mb-2">
          <b-card bg-variant="danger" text-variant="white">
            <b-row>
              <b-col cols="3" style="font-size: 2.5rem" class="text-center"
                ><b-icon
                  icon="x"
                  class="rounded-circle bg-primary p-2"
                  variant="light"
                ></b-icon
              ></b-col>
              <b-col>
                Crédito rejeitado<br /><b v-money-format="rejectedLoans" />
                <b-row
                  ><b-col class="text-right"
                    ><b-badge
                      @click="selectLoanList(2)"
                      variant="secondary"
                      pill
                      style="cursor: pointer; font-size: 12pt"
                      ><b-icon icon="eye" aria-hidden="true"></b-icon>
                      <small> Visualizar</small></b-badge
                    ></b-col
                  ></b-row
                >
              </b-col>
            </b-row>
          </b-card>
        </b-col>
      </b-row>
      <b-modal
        hide-footer
        ref="show-pending-loans"
        :title="selectedLoanDescription"
      >
        <LoansList :selectLoanList="selectedLoanList" />
      </b-modal>
    </b-overlay>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import NavBarVue from "@/components/NavBar";
import moment from "moment";
import LoansList from "@/components/loans/LoansList.vue";

export default {
  data: () => ({
    today: moment(),
    activeLoans: 0,
    pendingLoans: 0,
    rejectedLoans: 0,
    companyLoanList: [],
    selectedLoanDescription: "",
    selectedLoanList: [],
  }),

  components: {
    NavBarVue,
    LoansList,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "users",
      "token",
      "company",
      "companyLoans",
      "accounts",
      "customers",
      "dueInstallments",
      "upcomingInstallments",
      "updatedPassword",
    ]),
  },

  watch: {
    companyLoans: function () {
      this.populateCompanyLoans();
    },
  },

  created() {
    this.checkPasswordStatus();
  },

  methods: {
    selectLoanList(list) {
      if (list == 1) {
        this.selectedLoanDescription = "Financiamentos pendentes.";
        this.selectedLoanList = this.companyLoanList.filter((credit) => {
          return credit.status == 0;
        });
      } else if (list == 2) {
        this.selectedLoanDescription = "Financiamentos rejeitados.";
        this.selectedLoanList = this.companyLoanList.filter((credit) => {
          return credit.status == -1;
        });
      }
      this.$refs["show-pending-loans"].show();
    },

    checkPasswordStatus() {
      this.user.updatedPassword == 1 ? "" : this.$router.replace("/profile");
    },

    goToCustomers() {
      this.$router.replace("/customers");
    },

    openCustomerPanel(accountNumber) {
      const filteredCustomer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      this.$store.commit("SET_CURRENT_CUSTOMER", filteredCustomer[0]);
      this.$router.replace("/customer");
    },

    syncLoans() {
      if (this.user.userRole === 1) {
        this.companyLoanList = this.companyLoans;
      } else {
        const list = this.companyLoans.filter((a) => {
          return a.creditManager == this.user.id;
        });
        this.companyLoanList = list;
      }
    },

    populateCompanyLoans() {
      this.syncLoans();
      // Disbursed Loans
      const disbursedLoan = this.companyLoanList.filter((credit) => {
        return credit.status == 1;
      });
      this.activeLoans = disbursedLoan.reduce((sum, p) => sum + p.amount, 0);

      // Pending Loans
      const pendingLoan = this.companyLoanList.filter((credit) => {
        return credit.status == 0;
      });
      this.pendingLoans = pendingLoan.reduce((sum, p) => sum + p.amount, 0);

      // Disbursed Loans
      const rejectedLoan = this.companyLoanList.filter((credit) => {
        return credit.status == -1;
      });

      this.rejectedLoans = rejectedLoan.reduce((sum, p) => sum + p.amount, 0);
    },
  },
};
</script>
<style scoped></style>
