<template>
  <b-list-group>
    <b-list-group-item
      v-for="(loan, index) in loanList"
      :key="index"
      class="d-flex align-items-center"
      style="cursor: pointer"
      @click="openCustomerPanel(loan.accountNumber)"
    >
      <b-avatar
        :text="getCustomer(loan.accountNumber).charAt(0)"
        class="mr-3"
      ></b-avatar>
      <span class="mr-auto"
        >{{ getCustomer(loan.accountNumber) }}
        <br />
        <em style="font-size: 8pt" v-date-format="loan.createdAt"></em
      ></span>
      <div class="text-center text-secondary">
        <b style="font-size: 8pt" v-money-format="loan.amount" /><br />
        <em
          ><small style="font-size: 8pt"
            >{{ loan.interestRate * 100 }}%</small
          ></em
        >
      </div>
    </b-list-group-item>
  </b-list-group>
</template>

<script>
import { mapGetters } from "vuex";
import FilterCustomer from "@/utils/filterCustomer";
import moment from "moment";

export default {
  name: "item-loan",

  props: ["selectLoanList"],

  data: () => ({ today: moment(), loanList: [] }),

  created() {
    if (this.user.userRole === 1) {
      this.loanList = this.selectLoanList;
    } else {
      const list = this.selectLoanList.filter((a) => {
        return a.creditManager == this.user.id;
      });
      this.loanList = list;
    }
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "customers",
      "currentCustomer",
      "customerLoans",
      "customerTranzactions",
      "company",
    ]),
  },

  methods: {
    getCustomer(accountNumber) {
      return FilterCustomer.filter(this.customers, accountNumber).customerName;
    },

    openCustomerPanel(accountNumber) {
      const filteredCustomer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      this.$store.commit("SET_CURRENT_CUSTOMER", filteredCustomer[0]);
      this.$router.replace("/customer");
    },
  },
};
</script>
